(function () {
  "use strict";

  var catalogue = window.T6_COURSES || {};

  function rotateOptions(correct, wrong, shift) {
    var values = [correct].concat(wrong).slice(0, 4);
    var amount = ((shift % values.length) + values.length) % values.length;
    var options = values.slice(amount).concat(values.slice(0, amount));
    return {options: options, answer: options.indexOf(correct)};
  }

  function makeQuestion(courseId, concept, perspective, stem, correct, wrong, caselet, shift) {
    var set = rotateOptions(correct, wrong, shift);
    return {
      id: concept.id + "_" + perspective,
      courseId: courseId,
      conceptId: concept.id,
      module: concept.module,
      source: concept.source,
      node: concept.name,
      pattern: perspective === "explain" ? "Concept check" : perspective === "apply" ? "Application" : "Concept connection",
      perspective: perspective,
      caselet: caselet || "",
      stem: stem,
      options: set.options,
      answer: set.answer,
      explanation: concept.summary,
      link: concept.bridge
    };
  }

  function makeCourse(config) {
    var questions = {};
    var byModule = {};
    config.concepts.forEach(function (concept, index) {
      byModule[concept.module] = byModule[concept.module] || [];
      byModule[concept.module].push(concept);

      var explain = makeQuestion(
        config.id, concept, "explain", "Which statement best explains " + concept.name + "?",
        concept.summary, concept.confusions, "", concept.module + index
      );
      var apply = makeQuestion(
        config.id, concept, "apply", "What is the best interpretation or next step?",
        concept.application, concept.applicationWrong, concept.caselet, concept.module + index + 1
      );
      var connect = makeQuestion(
        config.id, concept, "connect", "Which explanation best connects this idea to the wider subject?",
        concept.bridge,
        [
          "It improves one local measure, so effects elsewhere in the system no longer matter.",
          "Once this choice is made, later evidence should not change the decision.",
          "It works independently of the people, constraints, and decisions around it."
        ],
        "A student understands the definition but needs to explain why the idea changes the next decision.",
        concept.module + index + 2
      );
      explain.repairId = apply.id;
      apply.repairId = connect.id;
      connect.repairId = explain.id;
      questions[explain.id] = explain;
      questions[apply.id] = apply;
      questions[connect.id] = connect;
    });

    config.synthesis.forEach(function (item, index) {
      var concept = config.concepts.filter(function (entry) { return entry.id === item.conceptId; })[0];
      var set = rotateOptions(item.correct, item.wrong, index + 1);
      questions[item.id] = {
        id: item.id,
        courseId: config.id,
        conceptId: item.conceptId,
        module: concept.module,
        source: item.source,
        node: item.node,
        pattern: "Mixed case",
        perspective: "synthesis",
        caselet: item.caselet,
        stem: item.stem,
        options: set.options,
        answer: set.answer,
        explanation: item.explanation,
        link: item.link,
        repairId: concept.id + "_apply"
      };
    });

    var runs = [];
    for (var module = 1; module <= 8; module += 1) {
      var moduleConcepts = byModule[module];
      runs.push({
        id: module,
        module: module,
        title: config.modules[module - 1],
        subtitle: moduleConcepts.map(function (concept) { return concept.name; }).join(" · "),
        minutes: 7,
        questionIds: moduleConcepts.reduce(function (ids, concept) {
          return ids.concat([concept.id + "_explain", concept.id + "_apply"]);
        }, [])
      });
    }
    runs.push({
      id: 9,
      module: 9,
      title: "Connect the whole subject",
      subtitle: "One cause-and-effect question from every module",
      minutes: 11,
      questionIds: config.concepts.filter(function (_, index) { return index % 2 === 0; }).map(function (concept) { return concept.id + "_connect"; })
    });
    runs.push({
      id: 10,
      module: 10,
      title: "Full practice mock",
      subtitle: "Twelve mixed concept and case questions",
      minutes: 18,
      mock: true,
      questionIds: config.concepts.filter(function (_, index) { return index % 2 === 1; }).map(function (concept) { return concept.id + "_connect"; })
        .concat(config.synthesis.map(function (item) { return item.id; }))
    });

    return {
      id: config.id,
      title: config.title,
      shortTitle: config.shortTitle,
      description: config.description,
      modules: config.modules,
      chain: config.modules,
      concepts: config.concepts,
      runs: runs,
      questions: questions
    };
  }

  function enrichBrgsa(course) {
    var concepts = [
      {id:"brgsa_m1_demand",module:1,source:"BRGSA-M01-L01",name:"Demand validation",match:/lean|validat|landing|smoke|survey/i},
      {id:"brgsa_m1_evidence",module:1,source:"BRGSA-M01-L04",name:"Strength of evidence",match:/commit|pre.order|evidence|signal/i},
      {id:"brgsa_m2_design",module:2,source:"BRGSA-M02-L01",name:"Experiment design",match:/null|sample|experiment|proxy/i},
      {id:"brgsa_m2_error",module:2,source:"BRGSA-M02-L03",name:"Decision errors",match:/type|error|false|cost/i},
      {id:"brgsa_m3_cohort",module:3,source:"BRGSA-M03-L01",name:"Cohorts and retention",match:/cohort|retention|shape/i},
      {id:"brgsa_m3_economics",module:3,source:"BRGSA-M03-L04",name:"CAC and LTV",match:/cac|ltv|economic|scale/i},
      {id:"brgsa_m4_constraint",module:4,source:"BRGSA-M04-L02",name:"Growth constraint",match:/constraint|discipline|stage/i},
      {id:"brgsa_m4_customers",module:4,source:"BRGSA-M04-L04",name:"First customers",match:/customer|founder|acqui/i},
      {id:"brgsa_m5_channel",module:5,source:"BRGSA-M05-L01",name:"Channel fit",match:/channel|outbound|organic|loop/i},
      {id:"brgsa_m5_activation",module:5,source:"BRGSA-M05-L05",name:"Activation",match:/aha|activat|friction/i},
      {id:"brgsa_m6_habit",module:6,source:"BRGSA-M06-L01",name:"Habit and lifecycle",match:/habit|lifecycle|retention/i},
      {id:"brgsa_m6_churn",module:6,source:"BRGSA-M06-L05",name:"Churn and referral",match:/churn|referral|network/i},
      {id:"brgsa_m7_pricing",module:7,source:"BRGSA-M07-L01",name:"Pricing and NRR",match:/pricing|nrr|revenue/i},
      {id:"brgsa_m7_pipeline",module:7,source:"BRGSA-M07-L04",name:"Pipeline and payback",match:/pipeline|handoff|payback|motion/i},
      {id:"brgsa_m8_priority",module:8,source:"BRGSA-M08-L01",name:"Prioritisation",match:/ice|backlog|priorit|allocation/i},
      {id:"brgsa_m8_decision",module:8,source:"BRGSA-M08-L03",name:"Decision rules",match:/decision|rule|vanity|metric/i}
    ];
    var modules = ["Validate demand", "Design fair tests", "Read the evidence", "Find the growth constraint", "Acquire and activate", "Retain customers", "Price and sell", "Operate the system"];
    Object.keys(course.questions).forEach(function (id) {
      var question = course.questions[id];
      var sourceModule = Number((String(question.source).match(/-M(\d\d)-/) || [0, question.module])[1]);
      var module = sourceModule >= 1 && sourceModule <= 8 ? sourceModule : Math.min(8, Math.max(1, question.module || 1));
      var candidates = concepts.filter(function (concept) { return concept.module === module; });
      var text = [id, question.node, question.stem].join(" ");
      var concept = candidates.filter(function (entry) { return entry.match.test(text); })[0] || candidates[id.length % candidates.length];
      question.courseId = "BRGSA";
      question.conceptId = concept.id;
      question.perspective = /case|application|decision|synthesis/i.test(question.pattern || "") ? "apply" : "explain";
    });
    concepts.forEach(function (concept) { delete concept.match; });
    course.description = "Business research, growth decisions, customer behaviour, and analytics.";
    course.modules = modules;
    course.chain = modules;
    course.concepts = concepts;
    course.runs[8].title = "Connect the whole subject";
    course.runs[8].subtitle = "One cause-and-effect question from every module";
    course.runs[9].title = "Full practice mock";
    course.runs[9].subtitle = "Twelve mixed concept and case questions";
    return course;
  }

  if (window.T6_COURSE) catalogue.BRGSA = enrichBrgsa(window.T6_COURSE);

  catalogue.IBM = makeCourse({
    id: "IBM",
    title: "Inclusive Business Models",
    shortTitle: "IBM",
    description: "How financially sustainable organisations serve underserved people and measure real impact.",
    modules: ["Inclusive business basics","Affordable health and education","Responsible finance and agriculture","Rural employment models","Shared value and energy access","Informal work and waste","Farmer organisations and social business","Impact investment and measurement"],
    concepts: [
      {id:"ibm_inclusive",module:1,source:"IBM-M01-L03",name:"Inclusive business",summary:"An inclusive business is built to meet a specific need of underserved people while remaining financially sustainable.",confusions:["Any profitable firm is inclusive if it sells a useful product.","An inclusive business must maximise shareholder profit before social outcomes.","Only grant-funded charities can be inclusive."],caselet:"A clinic serves low-income districts, charges enough to cover operations, and reinvests to expand access.",application:"Treat it as an inclusive business because serving an underserved need is the primary purpose and the model is designed to sustain itself.",applicationWrong:["Treat it as ordinary CSR because all social activity sits outside a business model.","Reject it as inclusive because charging any fee cancels social purpose.","Call it inclusive only if shareholder return is its sole objective."],bridge:"Financial sustainability keeps the social solution available; the underserved need determines what the model is built to do."},
      {id:"ibm_bop",module:1,source:"IBM-M01-L07",name:"Bottom-of-the-pyramid design",summary:"Serving bottom-of-the-pyramid markets requires products, prices, and delivery systems redesigned for structural constraints rather than smaller copies of rich-market offers.",confusions:["The model depends only on very high margins per customer.","A product becomes inclusive as soon as it is sold in a developing economy.","Existing premium products can be moved unchanged into poorer markets."],caselet:"A company wants rural adoption but its pack size, payment schedule, and service network assume high monthly income and urban access.",application:"Redesign affordability, access, and service around the market's constraints before treating population size as demand.",applicationWrong:["Keep the offer unchanged because a large population guarantees conversion.","Raise the pack size so each sale produces a larger margin.","Target only wealthy urban buyers while calling it a bottom-of-the-pyramid model."],bridge:"A large underserved population becomes a market only when the offer removes the affordability and access barriers that suppress use."},
      {id:"ibm_vaatsalya",module:2,source:"IBM-M02-L04",name:"No-frills healthcare access",summary:"Vaatsalya placed low-cost primary and secondary hospitals in semi-urban areas to reduce the travel and access burden faced by underserved patients.",confusions:["Its main advantage was adding premium tertiary care in major cities.","It solved access by sending every rural patient to urban hospitals.","The model depended on avoiding quality controls to reduce cost."],caselet:"A hospital chain sees rural patients travelling hours for routine and secondary care while city hospitals remain crowded.",application:"Locate a focused, quality-controlled facility nearer the underserved population and design its costs around essential care.",applicationWrong:["Open another premium tertiary hospital in the city.","Remove trained staff so price falls regardless of quality.","Offer only a transport subsidy without addressing local care capacity."],bridge:"Where care is located changes who can use it; cost discipline matters only if essential quality and access remain intact."},
      {id:"ibm_aravind",module:2,source:"IBM-M02-L08",name:"Process specialisation in healthcare",summary:"Aravind increased cataract capacity by standardising pre- and post-operative work for trained paramedics while surgeons focused on the surgery itself.",confusions:["Every activity stayed with the surgeon to preserve utilisation.","Capacity increased mainly by reducing the number of patients treated.","The model removed judgement from the surgical step."],caselet:"A scarce surgeon spends much of the day on repeatable preparation and follow-up while patients wait for operations.",application:"Separate standardisable tasks for trained support staff so the specialist concentrates on the constrained surgical step.",applicationWrong:["Ask the surgeon to perform every task to keep the process consistent.","Reduce theatre use so staff have more idle time.","Let untrained staff perform the surgery as well as preparation."],bridge:"Specialisation raises throughput when routine work is separated from the scarce expert task without lowering clinical quality."},
      {id:"ibm_grameen",module:3,source:"IBM-M03-L03",name:"Group-based microfinance",summary:"The classic Grameen model used local group knowledge, sequential lending, meetings, and peer accountability to lend without traditional collateral.",confusions:["It replaced borrower assessment with unlimited individual lending.","It depended on a credit bureau selecting every village borrower.","All group members received large loans at the same time without conditions."],caselet:"A lender cannot observe rural borrowers well and conventional collateral is unavailable, but neighbours know each other's reliability.",application:"Use carefully formed groups, staged lending, and local monitoring to make community knowledge part of risk assessment.",applicationWrong:["Issue repeated loans without checking repayment capacity.","Ignore group knowledge and lend only on sales-agent targets.","Require urban property collateral from every applicant."],bridge:"Local information can reduce screening risk, but the structure works only when repayment capacity and group discipline remain real."},
      {id:"ibm_responsible_lending",module:3,source:"IBM-M03-L05",name:"Responsible lending",summary:"Responsible lending checks total debt and repayment capacity instead of rewarding loan volume that can push households into over-indebtedness.",confusions:["More simultaneous loans always prove stronger financial inclusion.","A prior lender's approval removes the need for fresh due diligence.","Sales incentives are a reliable substitute for capacity checks."],caselet:"A household uses a new microloan to repay several older microloans, while agents are paid for each additional disbursement.",application:"Pause new lending, assess total obligations and cash flow, and correct incentives that reward volume over borrower capacity.",applicationWrong:["Approve quickly because earlier lenders must have checked.","Add another loan so the household can maintain repayments.","Judge success only by the number of accounts opened."],bridge:"Access becomes harmful when debt service outruns income; scale must preserve the screening practices that made inclusion viable."},
      {id:"ibm_rural_bpo",module:4,source:"IBM-M04-L04",name:"Rural BPO model",summary:"RuralShores adapted BPO work, training, language, location, and employment practices to rural conditions while competing on service quality.",confusions:["It copied an urban international-call-centre model without changes.","Its clients accepted poor service because the mission was social.","It created impact mainly by selling consumer goods to rural workers."],caselet:"A rural centre has capable local youth and multilingual demand, but international voice work and urban shift norms are a poor fit.",application:"Choose suitable domestic processes, train local staff, and adapt operations without relaxing client service standards.",applicationWrong:["Compete only for English-heavy international voice work.","Ask clients to accept lower quality as a social contribution.","Move the centre to a metro and retain the rural label."],bridge:"The model creates employment because business processes are redesigned around local capability while market-facing quality remains credible."},
      {id:"ibm_replication",module:4,source:"IBM-M04-L05",name:"Replicating rural services",summary:"Rural service models scale through trusted local partners, standard quality, training, and complementary relationships rather than capital-heavy central control alone.",confusions:["Replication means every centre must be owned and run directly.","Local partners matter only after national scale is reached.","Low price is enough to win outsourced critical work."],caselet:"A rural BPO wants to enter many small towns but lacks local knowledge and cannot fund every centre itself.",application:"Use a controlled partner model with local credibility, training, certification, and shared operating standards.",applicationWrong:["Own every centre regardless of capital and local acceptance.","Let each partner invent service standards independently.","Rely only on discounts and omit quality certification."],bridge:"Local partnership lowers entry friction and capital needs; common standards stop distributed growth from weakening trust."},
      {id:"ibm_shared_value",module:5,source:"IBM-M05-L07",name:"Shared value",summary:"Shared value expands economic value by solving social problems through the business model so stakeholders beyond shareholders benefit from the value created.",confusions:["It is simply redistributing profit after harmful operations continue.","Any profitable activity creates shared value automatically.","It requires the firm to stop earning a return."],caselet:"A buyer raises farmer productivity and product quality, lowering supply risk while farmers earn more.",application:"Evaluate whether the operating model creates additional value for both the firm and farmers rather than merely donating after profit is made.",applicationWrong:["Count it as shared value only if the firm loses money.","Ignore farmer outcomes because profitability proves the claim.","Classify any statutory donation as an integrated supply-chain model."],bridge:"The business becomes more durable when solving a stakeholder constraint also strengthens the economics that fund the solution."},
      {id:"ibm_selco",module:5,source:"IBM-M05-L10",name:"SELCO affordability system",summary:"SELCO linked customised solar products with independent finance and reliable service so energy access could support income and repay its own cost.",confusions:["Affordability meant giving every customer the same free product.","SELCO maximised sales by also approving its own customer loans.","After-sale service was optional because solar equipment has no downtime risk."],caselet:"A street vendor spends ₹15 a day on kerosene and could use a solar light financed at ₹10 a day, provided failures are repaired quickly.",application:"Bundle a suitable light with third-party finance and dependable service, linking repayment to the customer's savings or added income.",applicationWrong:["Sell the largest system available and let SELCO approve the debt itself.","Ignore servicing because the purchase has already happened.","Require the full price upfront despite the customer's daily cash flow."],bridge:"Product, finance, livelihood benefit, and uptime form one affordability system; removing any link can make the offer unusable."},
      {id:"ibm_labournet",module:6,source:"IBM-M06-L02",name:"LabourNet platform",summary:"LabourNet sought to improve informal workers' mobility through identity, skills, market links, and institutional access while building a sustainable enterprise.",confusions:["It addressed informal work only by issuing one-time grants.","Its model assumed migrant workers already had trusted identities and bank access.","The platform worked by preventing workers from changing employers."],caselet:"Migrant workers spend time finding jobs, lack verifiable identity, and are treated as high risk by formal institutions.",application:"Build trusted worker records, skills, job-market connections, and links to financial or insurance institutions together.",applicationWrong:["Offer a job listing without solving identity or trust.","Exclude mobile workers because their records are difficult.","Measure impact only by the number of registrations."],bridge:"Identity makes skills and work history legible; that trust opens market and institutional access that income mobility requires."},
      {id:"ibm_waste",module:6,source:"IBM-M06-L05",name:"Inclusive waste enterprise",summary:"An inclusive waste enterprise must create environmental value and viable products while protecting livelihoods and agency for waste workers.",confusions:["Selling recycled products is sufficient even if waste workers are worse off.","Environmental benefit cancels the need for financial viability.","Workers can only participate as low-paid employees."],caselet:"A venture turns temple flower waste into incense and natural dyes using women from low-income communities.",application:"Track pollution reduction, product economics, and whether workers gain fair, durable livelihood opportunities.",applicationWrong:["Claim inclusion from recycling alone without worker outcomes.","Ignore product demand because environmental intent guarantees survival.","Replace livelihood measures with total waste collected."],bridge:"Waste becomes shared value only when material recovery, customer demand, and worker welfare reinforce one another."},
      {id:"ibm_fpo",module:7,source:"IBM-M07-L04",name:"Farmer Producer Organisation",summary:"An FPO pools farmer ownership, volume, services, and market links so smallholders can build a viable business and stronger bargaining position.",confusions:["An FPO is owned only by an outside trader.","Its main purpose is to keep every farmer selling separately.","Market linkage becomes unnecessary once farmers contribute equity."],caselet:"Small farmers produce a distinctive rice but individually lack volume, branding, advice, and negotiating power.",application:"Aggregate through a farmer-owned organisation, build traceability and market links, and invest in value-adding capability.",applicationWrong:["Keep volumes fragmented and negotiate farm by farm.","Transfer ownership entirely to a distant buyer.","Focus on registration counts without building sales capability."],bridge:"Collective ownership turns fragmented production into scale, but market access and managerial capability convert that scale into income."},
      {id:"ibm_social_business",module:7,source:"IBM-M07-L05",name:"Social business",summary:"A social business prioritises social impact, aims not to make losses, and integrates the social purpose into operations rather than treating it as separate charity.",confusions:["It maximises distributable profit and treats impact as optional.","It is identical to employee volunteering.","It must depend permanently on grants and cannot earn revenue."],caselet:"A company creates a business line for affordable nutrition whose goal is impact, while prices cover costs and profits are not the primary objective.",application:"Judge it by whether the social goal drives the model and financial discipline keeps it operating without turning profit maximisation into the purpose.",applicationWrong:["Call it ordinary CSR because it sells a product.","Require maximum dividends before considering impact.","Treat losses as proof that the model is socially serious."],bridge:"A social purpose becomes repeatable when it sits inside a no-loss operating model instead of depending only on periodic donations."},
      {id:"ibm_impact_investing",module:8,source:"IBM-M08-L01",name:"Impact investing",summary:"Impact investing intentionally targets measurable social or environmental impact alongside a financial return; it is not a grant.",confusions:["Any investment in a profitable company is an impact investment.","Impact intent matters but measurement and reporting do not.","Impact investing excludes all financial return."],caselet:"A fund invests in affordable housing, sets access targets, reports outcomes, and expects the capital to earn a return.",application:"Classify it as impact investing because intent, measurement, and financial return are designed together.",applicationWrong:["Classify every housing share purchase as impact investing.","Treat it as philanthropy because it has a social target.","Ignore outcome reporting once the capital is deployed."],bridge:"Intent defines the desired change, measurement tests whether it occurred, and return keeps investment capital reusable."},
      {id:"ibm_impact_measurement",module:8,source:"IBM-M08-L05",name:"Impact measurement",summary:"Credible impact measurement compares outcomes against a suitable counterfactual so changes caused by the intervention are not confused with selection or outside factors.",confusions:["A before-and-after increase always proves causation.","Participants can be compared with any convenient non-participant group.","Self-selection improves causal confidence because motivated people change more."],caselet:"Borrowers who choose a programme earn more later, but they were more enterprising than non-borrowers before it began.",application:"Use a comparable control or another defensible counterfactual and account for selection before attributing the income change to the programme.",applicationWrong:["Attribute the full difference to the loan immediately.","Compare them with a richer unrelated village.","Use only participant testimonials as causal proof."],bridge:"A counterfactual separates change caused by the intervention from change that would have happened because of who participated or what else changed."}
    ],
    synthesis: [
      {id:"ibm_syn_access",conceptId:"ibm_aravind",source:"IBM-M02-L08",node:"Access and process",caselet:"A low-cost clinic is near its patients but the only specialist still performs every routine task.",stem:"Which change best joins access with operating capacity?",correct:"Keep the local access model and move standard preparation and follow-up to trained staff so the specialist handles the constrained procedure.",wrong:["Move the clinic back to a premium city location.","Let price fall by removing quality checks.","Increase advertising without changing the bottleneck."],explanation:"Location solves access; task specialisation solves the scarce-capacity constraint.",link:"Inclusive access holds only when the delivery process can serve demand at reliable quality."},
      {id:"ibm_syn_scale",conceptId:"ibm_responsible_lending",source:"IBM-M03-L05",node:"Scale without harm",caselet:"A lender doubles outreach by paying agents per loan while dropping group meetings and total-debt checks.",stem:"What is the central risk?",correct:"Scale has removed the screening and accountability that made lending inclusive, so outreach can become over-indebtedness.",wrong:["The model is safer because more loans always diversify household risk.","The only issue is that group meetings reduce advertising reach.","Repayment capacity matters only after a default occurs."],explanation:"Inclusive scale must preserve borrower protection and repayment-capacity checks.",link:"Growth that destroys the protective mechanism is not replication of the original model."},
      {id:"ibm_syn_value",conceptId:"ibm_shared_value",source:"IBM-M05-L07",node:"Value and inclusion",caselet:"A buyer's new process cuts its costs but pushes all weather and price risk onto small farmers.",stem:"Why is a shared-value claim weak?",correct:"The firm gained through risk transfer rather than creating additional value that also improves farmer outcomes.",wrong:["Shared value requires the buyer to make no profit.","Any supply-chain change is automatically inclusive.","Only donations can benefit farmers."],explanation:"Shared value expands value for connected stakeholders instead of extracting it from a weaker one.",link:"Profit and social benefit must arise from the same improved system, not from shifting harm."},
      {id:"ibm_syn_impact",conceptId:"ibm_impact_measurement",source:"IBM-M08-L05",node:"Finance to evidence",caselet:"An impact fund reports how many enterprises it financed but not whether intended social outcomes changed.",stem:"What is missing?",correct:"Outcome measurement against a credible baseline or comparison, not just a count of financial activity.",wrong:["A larger investment total, which automatically proves impact.","Removal of the financial-return target.","A list of every investor's personal motivation."],explanation:"Money deployed is an input; impact is the change that can reasonably be attributed to the financed activity.",link:"Impact investing becomes accountable when intentional capital is followed by credible outcome evidence."}
    ]
  });

  catalogue.SCLM = makeCourse({
    id:"SCLM",title:"Supply Chain and Logistics Management",shortTitle:"SCLM",description:"How demand, inventory, sourcing, transport, and coordination shape service and cost.",
    modules:["Strategy and performance drivers","Forecasting and planning","Inventory decisions","Sourcing and coordination","Re-engineering the network","Capacity and transport turnaround","Multimodal logistics and ports","Public logistics systems"],
    concepts:[
      {id:"sclm_fit",module:1,source:"SCLM-M01-L04",name:"Strategic fit",summary:"Strategic fit aligns the supply chain's efficiency and responsiveness with the customer promise and its implied uncertainty.",confusions:["Every supply chain should maximise responsiveness regardless of cost.","Competitive strategy and supply chain design can be chosen independently.","Stable demand always means low implied uncertainty even with extreme service promises."],caselet:"Marketing promises high variety and same-day availability while operations uses slow transport, long batches, and suppliers chosen only for low price.",application:"Redesign the supply chain for the promised responsiveness or change the customer promise so capabilities and expectations match.",applicationWrong:["Keep both strategies unchanged because each function is locally efficient.","Add more product variety without changing operations.","Measure only unit purchase price and ignore availability."],bridge:"The customer promise creates operating requirements; performance fails when the network is built for a different promise."},
      {id:"sclm_drivers",module:1,source:"SCLM-M01-L06",name:"Six supply-chain drivers",summary:"Facilities, inventory, transportation, information, sourcing, and pricing jointly set the balance between responsiveness and efficiency.",confusions:["Only transportation determines supply-chain performance.","Adding facilities always lowers total cost and inventory.","Each driver can be optimised independently without trade-offs."],caselet:"A quick-commerce firm adds small local fulfilment points and more local stock to reduce delivery time.",application:"Recognise a facilities-and-inventory choice that raises responsiveness while also increasing fixed cost and possibly total inventory.",applicationWrong:["Treat speed as a free result of better branding.","Assume more facilities must reduce every cost.","Ignore information and sourcing because location alone guarantees service."],bridge:"Managers deliver strategic fit by configuring several connected drivers, not by maximising one lever in isolation."},
      {id:"sclm_smoothing",module:2,source:"SCLM-M02-L06",name:"Exponential smoothing",summary:"Exponential smoothing updates the old forecast by a fraction alpha of the latest forecast error; a larger alpha reacts more strongly to recent demand.",confusions:["It discards the old forecast and uses only the latest actual.","A larger alpha always produces a smoother, slower response.","The forecast moves opposite to the latest error."],caselet:"Last period's forecast was 100, actual demand was 120, and alpha is 0.25.",application:"Move the next forecast upward by 25% of the 20-unit error, giving 105.",applicationWrong:["Set the next forecast to 120 because old information is discarded.","Move the forecast down to 95.","Keep it at 100 because smoothing never responds to error."],bridge:"Forecast error is the signal; alpha controls how quickly planning responds without throwing away accumulated history."},
      {id:"sclm_sop",module:2,source:"SCLM-M02-L12",name:"Sales and operations planning",summary:"S&OP balances forecast demand with capacity, utilisation, inventory, backlog, and outsourcing over a medium-term horizon.",confusions:["It is a daily dispatch schedule with no capacity decisions.","A chase plan always holds workforce and output constant.","A level plan changes capacity every period to equal demand."],caselet:"A plant with costly hiring and training faces seasonal demand, while its product can be stored economically.",application:"Use a more level production plan and build or draw down inventory, possibly mixing limited overtime or outsourcing.",applicationWrong:["Hire and fire exactly with each monthly demand change.","Ignore the forecast until daily orders arrive.","Use backlog even if customers will not tolerate delay."],bridge:"Forecasts become decisions only when demand is reconciled with the real cost and flexibility of capacity, inventory, and service."},
      {id:"sclm_eoq",module:3,source:"SCLM-M03-L03",name:"Economic order quantity",summary:"EOQ chooses an order size that balances annual ordering cost against holding cost under stable demand, lead time, price, and no-shortage assumptions.",confusions:["EOQ is designed primarily for one-season uncertain demand.","The model assumes frequent stockouts and changing unit prices.","The largest possible order is always optimal because it cuts ordering cost."],caselet:"A component has stable annual demand, fixed cost per order, constant lead time, no discounts, and known annual holding cost.",application:"Use EOQ for the lot size, while calculating reorder timing separately from demand during lead time.",applicationWrong:["Use a newsvendor critical ratio for the recurring order size.","Order a full year's demand because holding cost is irrelevant.","Treat EOQ as the reorder point itself."],bridge:"Lot size sets the ordering-versus-holding trade-off; reorder timing answers a different question about when replenishment must start."},
      {id:"sclm_newsvendor",module:3,source:"SCLM-M03-L05",name:"Newsvendor decision",summary:"The newsvendor model chooses a one-time quantity under uncertain demand by balancing the cost of one unit too few against one unit too many.",confusions:["It assumes demand is constant and replenishment repeats forever.","Only purchase cost matters in the critical decision.","Underage and overage costs affect the quantity in the same direction."],caselet:"A seller must choose one order for a short season; leftovers are discounted and unmet demand loses contribution and goodwill.",application:"Use a critical-ratio decision based on underage and overage costs to select the demand quantile.",applicationWrong:["Use EOQ because the order repeats throughout the year.","Order the mean regardless of margin and salvage value.","Ignore lost margin because only leftover stock is costly."],bridge:"The economic cost of being short versus long determines which point in the uncertain demand distribution is worth covering."},
      {id:"sclm_portfolio",module:4,source:"SCLM-M04-L04",name:"Tailored sourcing portfolio",summary:"A sourcing portfolio matches responsive sources to volatile, high-value or time-sensitive items and efficient sources to stable, predictable volume while managing disruption risk.",confusions:["One globally cheapest supplier is best for every item.","Innovative products must always be fully offshore.","Nearshoring removes all cost and disruption trade-offs."],caselet:"A firm sells one mature high-volume item and one volatile product with short life, high stockout cost, and frequent engineering changes.",application:"Use a low-cost source for stable volume and a faster, collaborative source for the volatile item, with risk hedges where justified.",applicationWrong:["Put both items with the longest-lead lowest-price supplier.","Use the responsive source only for the stable commodity.","Choose suppliers without considering disruption or obsolescence."],bridge:"Different demand and product risks require different source capabilities; a portfolio prevents one cost objective from governing every item."},
      {id:"sclm_bullwhip",module:4,source:"SCLM-M04-L05",name:"Bullwhip effect",summary:"The bullwhip effect is the amplification of order variability upstream even when end-customer demand changes only modestly.",confusions:["It is a fall in transport cost caused by stable ordering.","Upstream orders must be less variable than retail sales.","It occurs only when final demand has extreme swings."],caselet:"Retail sales move slightly, but retailer, wholesaler, and manufacturer orders show progressively larger peaks and troughs.",application:"Diagnose demand amplification and examine incentives, batching, forecast updates, lead times, and information distortion across stages.",applicationWrong:["Assume consumer demand itself must have moved by the same amount.","Ask each stage to optimise its own profit without shared information.","Add more safety stock without addressing order distortion."],bridge:"Small local reactions compound across stages; coordination and shared demand signals stop defensive decisions from amplifying uncertainty."},
      {id:"sclm_reengineering",module:5,source:"SCLM-M05-L06",name:"Supply-chain re-engineering",summary:"Re-engineering redesigns end-to-end flows to remove hidden time, inventory, hand-offs, and cost while meeting distinct customer service needs.",confusions:["It means cutting one department's cost without examining other stages.","More inventory is the default answer to every service problem.","Customer segments should receive identical logistics regardless of need."],caselet:"A firm has long queues between stages, excess stock, repeated handling, and customers with very different speed requirements.",application:"Map the full flow, expose waiting and indirect costs, segment service needs, and redesign the connected process rather than one function.",applicationWrong:["Optimise each warehouse separately and ignore upstream effects.","Add buffer stock at every hand-off.","Give every segment the most expensive service level."],bridge:"Time and inventory hide between organisational boundaries; end-to-end redesign makes those costs and customer trade-offs visible."},
      {id:"sclm_stockyard",module:5,source:"SCLM-M05-L13",name:"Stockyard location trade-off",summary:"Stockyard design balances primary and secondary transport cost, service-distance limits, throughput constraints, and inventory instead of choosing the fewest sites automatically.",confusions:["The geographically central site is always optimal.","Primary and secondary movement have the same cost in every scenario.","A location model should ignore minimum viable throughput."],caselet:"Secondary delivery becomes more expensive than primary line-haul and dealers require an overnight service radius.",application:"Re-evaluate site locations using the changed cost structure, coverage limit, demand, and minimum throughput together.",applicationWrong:["Keep old sites because demand alone determines location.","Choose one site regardless of dealer distance.","Minimise primary distance while excluding secondary cost."],bridge:"A network location changes both legs of transport and facility utilisation; service constraints turn the cheapest map into a feasible operating design."},
      {id:"sclm_coldstore",module:6,source:"SCLM-M06-L05",name:"Cold-storage expansion",summary:"Cold-storage expansion must be judged through seasonal utilisation, commodity flows, operating cost, financing, and market relationships—not capacity alone.",confusions:["A profitable existing site proves any new geography will work.","Debt structure and seasonal demand do not affect expansion risk.","Cold storage earns the same return at every utilisation level."],caselet:"An efficient operator considers a new city with different commodity flows, trader relationships, seasonal demand, and refrigerated transport needs.",application:"Test local utilisation, customer and commodity fit, operating economics, logistics, and financing before replicating the facility.",applicationWrong:["Copy the current facility because management skill transfers automatically.","Decide only from available land price.","Assume capacity will remain full throughout the year."],bridge:"An operating capability creates value only when local demand, logistics, and capital structure keep expensive capacity productively used."},
      {id:"sclm_turnaround",module:6,source:"SCLM-M06-L07",name:"Transport turnaround",summary:"Turnaround improves asset throughput by removing waiting from the full trip cycle; Rajashree targeted locomotive detention so the same rakes could make more trips.",confusions:["Throughput can rise only by buying more wagons.","Loading speed is the only time that matters in a rail cycle.","Idle waiting after loading does not affect annual capacity."],caselet:"A loaded rake waits an average 13 hours for a locomotive, limiting monthly trips despite adequate loading capacity.",application:"Coordinate an engine-on-load arrangement and accountability for the hand-off so detention falls and trips per rake rise.",applicationWrong:["Buy rakes before addressing the 13-hour wait.","Increase factory output while loaded wagons remain idle.","Measure only tonnes per wagon and ignore cycle time."],bridge:"Removing non-value waiting increases the productive cycles of the same asset, linking coordination directly to capacity."},
      {id:"sclm_multimodal",module:7,source:"SCLM-M07-L06",name:"Multimodal cost trade-off",summary:"Mode choice compares end-to-end transport, handling, port, inventory, lot-size, and service effects—not freight rate alone.",confusions:["The lowest line-haul price is always the lowest total logistics cost.","Large sea lots never create inventory cost.","Handling and first/last-mile legs can be ignored in mode comparison."],caselet:"Sea freight is far cheaper per tonne than rail but arrives in one very large annual lot and requires port, barge, and inland handling.",application:"Compare total movement cost plus inventory and handling created by the shipment size before choosing the sea option.",applicationWrong:["Choose sea immediately from the line-haul rate.","Choose rail only because it uses smaller vehicles.","Exclude port and inland legs from both options."],bridge:"A mode changes shipment size, time, handling, and stock as well as freight; total logistics cost joins those consequences."},
      {id:"sclm_ports",module:7,source:"SCLM-M07-L07",name:"Ports and PPP",summary:"Ports support trade and coastal movement; public-private participation can add capacity and operating capability, but performance still depends on connected infrastructure and governance.",confusions:["Port performance is determined only by public ownership.","Container traffic can move without hinterland links.","Private participation automatically removes every maritime constraint."],caselet:"A terminal adds modern handling capacity, but road and rail evacuation remain congested and ships still face delays.",application:"Treat terminal investment, hinterland connectivity, coordination, and service performance as one port system.",applicationWrong:["Declare the port fixed because cranes are newer.","Measure only total national coastline.","Remove performance oversight after private investment."],bridge:"A port is a transfer node, so capacity creates trade value only when sea-side operations and inland flows work together."},
      {id:"sclm_leads",module:8,source:"SCLM-M08-L01",name:"LEADS index",summary:"LEADS uses stakeholder perceptions and operating indicators to compare state logistics strengths and improvement areas and encourage policy competition.",confusions:["It is a direct count of warehouse square footage only.","It ranks countries rather than Indian states and union territories.","A high score proves every firm in the state has low logistics cost."],caselet:"A state ranks poorly on tracking, infrastructure, regulatory environment, and cargo safety in stakeholder surveys.",application:"Use the dimensions to target state-level policy and infrastructure improvements while recognising the measure is perception-based.",applicationWrong:["Treat the rank as a firm-level profit statement.","Improve only warehouse capacity because other pillars are irrelevant.","Ignore stakeholder evidence because the index is not a customs tariff."],bridge:"A shared diagnostic makes system weaknesses visible and gives states a basis for coordinated improvement, not a guarantee of firm performance."},
      {id:"sclm_akshaya",module:8,source:"SCLM-M08-L03",name:"Akshaya Patra meal logistics",summary:"Akshaya Patra coordinates menu, mechanised production, labelled containers, route sequencing, vehicles, hygiene, and school time windows as one high-volume service system.",confusions:["Cooking volume alone determines successful meal delivery.","Route labels and loading sequence have no effect on service.","Nutritional standards can be separated from menu and logistics design."],caselet:"A central kitchen meets cooking targets, but unlabeled containers and poorly sequenced loading cause late and incorrect school deliveries.",application:"Integrate route-wise packaging, loading order, vehicle capacity, meal windows, and food-safety controls with production.",applicationWrong:["Cook more food without changing dispatch.","Remove menu and school identifiers to speed packing.","Measure success only at the kitchen exit."],bridge:"Public service quality is completed at the recipient, so production, routing, timing, and safety must hold together end to end."}
    ],
    synthesis:[
      {id:"sclm_syn_fit",conceptId:"sclm_drivers",source:"SCLM-M01-L06",node:"Strategy to drivers",caselet:"A retailer promises low prices and dependable availability but keeps many premium express facilities with duplicated stock.",stem:"Which diagnosis is best?",correct:"Its facilities and inventory choices may be more responsive—and costly—than the competitive promise requires, so the driver configuration lacks strategic fit.",wrong:["More facilities always improve both efficiency and responsiveness.","Pricing and supply-chain choices are unrelated.","The only useful response is to add product variety."],explanation:"Supply-chain drivers should deliver the promised service at the appropriate cost.",link:"Strategy becomes operational through the configuration of facilities, inventory, transport, information, sourcing, and pricing."},
      {id:"sclm_syn_forecast",conceptId:"sclm_sop",source:"SCLM-M02-L12",node:"Forecast to plan",caselet:"A forecast rises sharply, but the plant has long training times and cheap storage.",stem:"What should planning do next?",correct:"Translate the forecast into a capacity-and-inventory plan, likely using stable capacity with inventory and limited flexibility rather than blindly chasing demand.",wrong:["Use the forecast as the production order without checking capacity.","Fire and rehire workers each period regardless of cost.","Ignore inventory because forecasting and operations are separate."],explanation:"S&OP converts forecasts into a feasible, profitable response across operational levers.",link:"A forecast has value only when its uncertainty and timing shape a feasible operating plan."},
      {id:"sclm_syn_inventory",conceptId:"sclm_newsvendor",source:"SCLM-M03-L05",node:"Choose the inventory model",caselet:"A fashion item has one buying opportunity, uncertain seasonal demand, and heavy markdowns after the season.",stem:"Which model fits best and why?",correct:"Newsvendor, because it is a one-time uncertain decision governed by the costs of shortage and leftover stock.",wrong:["EOQ, because demand is constant and orders repeat indefinitely.","Exponential smoothing alone, because it directly chooses the profit-maximising order.","A Q review model, because replenishment can occur continuously after the season."],explanation:"Model choice follows the structure of the decision, not the fact that inventory is involved.",link:"Recurring stable replenishment and one-shot uncertain stocking require different cost logic."},
      {id:"sclm_syn_flow",conceptId:"sclm_turnaround",source:"SCLM-M06-L07",node:"Network flow",caselet:"A network adds stockyards and vehicles, yet orders remain late because loaded assets wait at every organisational hand-off.",stem:"What should be investigated first?",correct:"End-to-end cycle time and hand-off coordination, because idle detention can consume capacity despite more physical assets.",wrong:["Only purchase price of the new vehicles.","A larger safety-stock target at every node.","Removal of shared performance measures."],explanation:"Waiting time can be the binding capacity constraint in a network full of assets.",link:"Network design and operating coordination meet in the time an order or asset spends between useful steps."}
    ]
  });

  catalogue.SPMS = makeCourse({
    id:"SPMS",title:"Software Product Management and Strategy",shortTitle:"SPMS",description:"How product teams choose problems, markets, business models, plans, and responsible operating decisions.",
    modules:["Product foundations","Markets and adoption","Positioning and business models","Pricing and unit economics","Competition and communication","Requirements and traceability","Priorities and roadmaps","Metrics and privacy"],
    concepts:[
      {id:"spms_dfv",module:1,source:"SPMS-M01-L05",name:"Desirability, feasibility, viability",summary:"A product opportunity must be wanted by customers, technically achievable, and economically sustainable; strength in only two dimensions leaves a predictable failure.",confusions:["Desirability means the team can engineer the product.","Viability is proven whenever users say they like an idea.","A feasible and profitable concept does not need customer demand."],caselet:"A team can build a device and sell it at a margin, but research shows no meaningful customer problem or willingness to use it.",application:"Treat desirability as the missing test before investing further, despite feasibility and apparent unit margin.",applicationWrong:["Launch because technical feasibility proves demand.","Reduce engineering scope even though feasibility is already established.","Call it viable and assume customers will learn to want it."],bridge:"A product survives only where customer value, engineering reality, and business economics overlap; one cannot compensate indefinitely for another."},
      {id:"spms_jtbd",module:1,source:"SPMS-M01-L10",name:"Jobs to be done",summary:"Jobs to be done focuses on the functional, emotional, and social progress a customer seeks, not merely the product category or stated feature request.",confusions:["The job is a list of features customers ask developers to copy.","Only the functional task matters; confidence and social context are irrelevant.","A product category defines the same job for every user."],caselet:"A patient asks for online consultation but mainly needs quick access to a trusted doctor and confidence that the advice is legitimate.",application:"Design around access, trust, and reassurance rather than treating video calling itself as the complete job.",applicationWrong:["Optimise only video resolution because that is the named feature.","Assume all telehealth users value the same outcome.","Ignore the emotional need because it is not functional."],bridge:"Understanding the progress sought reveals which benefits create value and which features are only one possible means."},
      {id:"spms_tamsam",module:2,source:"SPMS-M02-L04",name:"TAM, SAM, and SOM",summary:"TAM is total theoretical demand, SAM is the portion the product and context can serve, and SOM is the realistic near-term share the firm can reach and win.",confusions:["SOM is always larger than SAM because it includes future markets.","TAM is the customers the current sales team will win this quarter.","Regulation, channel, and capability do not affect the serviceable market."],caselet:"A regulated Indian investing app could theoretically help global investors but can currently serve Indian online retail users and initially targets cost-conscious self-directed investors.",application:"Treat global investors as TAM, Indian online retail investors as SAM, and the reachable cost-conscious segment as SOM.",applicationWrong:["Call the initial segment TAM because it will be contacted first.","Call global investors SOM because the technology is digital.","Ignore regulation when defining SAM."],bridge:"Market sizing becomes actionable by narrowing theoretical need through service constraints to the customers the current product can actually win."},
      {id:"spms_chasm",module:2,source:"SPMS-M02-L10",name:"Crossing the chasm",summary:"Moving from early adopters to mainstream customers requires a focused beachhead, complete and reliable experience, references, support, integration, and lower adoption risk.",confusions:["Mainstream adoption follows automatically once innovators approve.","The best strategy is to broaden to every segment before building references.","Mainstream users tolerate more risk and missing support than early adopters."],caselet:"A new enterprise tool delights technical pioneers but mainstream buyers ask for uptime, integration, references, security, and support.",application:"Win a narrow beachhead with a complete, credible solution and use its references before expanding.",applicationWrong:["Add more experimental features for every possible segment.","Dismiss reliability concerns as resistance to innovation.","Target the whole market before proving one repeatable use case."],bridge:"Early enthusiasm proves possibility; mainstream adoption depends on reducing the practical and social risk of switching."},
      {id:"spms_positioning",module:3,source:"SPMS-M03-L02",name:"Product definition and positioning",summary:"Product definition clarifies what is being built and the problem it solves, while positioning explains the differentiated value to a target customer relative to alternatives.",confusions:["A positioning statement is an internal technical specification.","Product definition and positioning are identical feature lists.","Positioning does not require a target user or alternative."],caselet:"A team describes its payment product only as 'an API with new database tables' when speaking to small merchants.",application:"Translate the internal definition into customer positioning: who it serves, the payment problem solved, the benefit, and why it differs from alternatives.",applicationWrong:["Add more implementation detail to the customer message.","Remove the target segment so everyone feels included.","List features without stating the customer outcome."],bridge:"Definition aligns builders on the solution; positioning helps a chosen customer understand why that solution matters and is different."},
      {id:"spms_lean_canvas",module:3,source:"SPMS-M03-L06",name:"Lean Canvas",summary:"Lean Canvas adapts one-page business modelling for early-stage uncertainty by emphasising problem, solution, key metrics, and unfair advantage.",confusions:["It is used only to document a mature company's fixed operating model.","It removes customer segments and channels from business modelling.","Its purpose is to finalise every assumption before testing."],caselet:"An early startup needs to decide whether a problem is worth solving and which assumptions an MVP should test.",application:"Use Lean Canvas to expose problem, solution, metrics, advantage, segments, channels, costs, and revenue as testable assumptions.",applicationWrong:["Use it as a final audited financial statement.","Fill only the solution box and treat the rest as execution detail.","Avoid revising the canvas after evidence arrives."],bridge:"A compact model makes linked business assumptions visible so learning can change the whole system rather than one feature at a time."},
      {id:"spms_value_pricing",module:4,source:"SPMS-M04-L02",name:"Value-based pricing",summary:"Value-based pricing starts from measurable customer value and segment-specific willingness to pay, then designs the offering and price structure around that value.",confusions:["Price should always equal unit cost plus a fixed markup.","All customer segments receive the same value and should pay identically.","Value can be priced without being articulated or measured."],caselet:"Software saves one segment ₹10 lakh a year but saves another only ₹50,000, while serving both costs roughly the same.",application:"Use the different economic value and willingness to pay to shape segment-specific offers and price structure.",applicationWrong:["Charge both only from identical delivery cost.","Set price from the cheaper alternative's feature count alone.","Ignore measurable savings because software has low marginal cost."],bridge:"Pricing captures part of created value; clear segmentation and value evidence connect customer benefit to business viability."},
      {id:"spms_unit_economics",module:4,source:"SPMS-M04-L07",name:"Unit economics",summary:"Unit economics tests profitability at the relevant customer or transaction level using measures such as acquisition cost, gross contribution, lifetime value, churn, and payback.",confusions:["Rapid revenue growth proves healthy unit economics automatically.","CAC should be compared with total revenue rather than gross contribution.","A long payback period cannot create cash-flow risk if lifetime value is high."],caselet:"A subscription spends ₹1,000 to acquire a customer and earns ₹100 monthly gross profit from that customer.",application:"Recognise a ten-month CAC payback before considering retention, cash burn, and whether lifetime gross profit comfortably exceeds acquisition cost.",applicationWrong:["Call payback one month because the subscription bills monthly.","Compare CAC only with top-line company revenue.","Ignore churn because acquisition has already occurred."],bridge:"Growth consumes cash before contribution repays acquisition; per-unit economics shows whether scaling improves or deepens the problem."},
      {id:"spms_alternatives",module:5,source:"SPMS-M05-L02",name:"Competition and alternatives",summary:"Competition includes every current or potential way customers accomplish the job, including substitutes and doing nothing—not only similar products.",confusions:["Only firms with the same feature list are competitors.","Customers cannot compare a product with manual work or inaction.","Competition should be defined before understanding the customer job."],caselet:"A collaboration app compares itself only with two other apps, while prospects continue using email, spreadsheets, meetings, or no formal system.",application:"Evaluate those behaviours as alternatives because they compete for the same customer progress and switching decision.",applicationWrong:["Ignore them because they are not software products.","Study only companies using the same technology stack.","Assume customers will abandon current workflows after seeing more features."],bridge:"The customer's job defines the competitive field; positioning improves when the product beats the real behaviour it must replace."},
      {id:"spms_buyer_journey",module:5,source:"SPMS-M05-L04",name:"Buyer journey communication",summary:"Value communication should match the buyer's stage—from unawareness through consideration and decision—with the need, evidence, format, and channel useful at that moment.",confusions:["One feature-heavy message should be repeated at every stage.","Communication begins only after the customer purchases.","Channel and evidence do not need to match the buyer's questions."],caselet:"Potential users do not yet recognise a health-monitoring problem, but the campaign opens with a detailed comparison of advanced settings.",application:"First make the problem and relevant value understandable, then introduce alternatives and proof as the buyer advances.",applicationWrong:["Add more technical detail to the first message.","Wait until after purchase to explain the value.","Use the same decision-stage proof for unaware audiences."],bridge:"Customers need different information before they can take each next step; timing turns product value into understandable evidence."},
      {id:"spms_requirements",module:6,source:"SPMS-M06-L05",name:"Functional and quality requirements",summary:"Functional requirements state what the product must do; quality or non-functional requirements state how well or under what constraints it must do it.",confusions:["Security and performance are always optional feature requests.","A functional requirement describes only the user-interface colour.","Quality requirements do not need measurable conditions."],caselet:"A login system must authenticate users and block unauthorised access within a defined response time.",application:"Treat authentication as functional, and security and response-time conditions as quality requirements that constrain its implementation.",applicationWrong:["Treat every statement as the same feature label.","Omit security because login already exists.","Record response time only after release, not as a requirement."],bridge:"A capability is incomplete without the quality conditions that make it safe, usable, and compliant in the real product."},
      {id:"spms_traceability",module:6,source:"SPMS-M06-L08",name:"Requirements traceability",summary:"Traceability links a customer need through product requirements, implementation, and verification so scope and change decisions remain explainable.",confusions:["Traceability is only a list of developer tasks.","Once a requirement is written, its source and tests can be discarded.","Customer and project requirements should never be connected."],caselet:"A team cannot explain which user need a database field supports or which test proves the related requirement works.",application:"Create links from the originating need to the product requirement, implementation item, and verification evidence.",applicationWrong:["Keep each artifact in a separate unlinked document.","Delete the customer source after development starts.","Approve the field because it already exists in code."],bridge:"Traceability preserves the reason behind work, making change impact and completion evidence visible across the development chain."},
      {id:"spms_priority",module:7,source:"SPMS-M07-L01",name:"MoSCoW and RICE prioritisation",summary:"MoSCoW aligns necessity categories, while RICE compares reach, impact, confidence, and effort; both make trade-offs explicit rather than replacing judgement.",confusions:["Every stakeholder request should be a Must have.","RICE ignores effort and confidence.","A numeric score eliminates the need to examine assumptions."],caselet:"Two features differ in user reach, likely impact, evidence confidence, and engineering effort, while a legal capability is non-negotiable.",application:"Mark the legal capability as Must and use a transparent RICE comparison for discretionary features, then review assumptions.",applicationWrong:["Put all three in Must to avoid conflict.","Choose the idea with the highest impact claim and ignore confidence and effort.","Let the loudest stakeholder set the order."],bridge:"Prioritisation turns scarce capacity into an explicit decision by separating necessity from comparative value and evidence."},
      {id:"spms_roadmap",module:7,source:"SPMS-M07-L04",name:"Product roadmap",summary:"A roadmap translates product strategy into an adaptable sequence of outcomes and releases over time, with more detail and confidence near term than far term.",confusions:["A roadmap is an unchangeable promise of exact features and dates for years.","It is identical to the current sprint backlog.","Market and technology change should not affect it."],caselet:"A team publishes exact five-year feature dates although technology, regulation, and customer evidence are changing quickly.",application:"Keep the strategic direction and outcome sequence, but express distant work with lower detail and update it as evidence changes.",applicationWrong:["Freeze every feature date to protect the original plan.","Remove long-term direction and keep only today's tasks.","Treat the roadmap as a sales contract with no uncertainty."],bridge:"A roadmap gives direction without pretending distant uncertainty is resolved; learning should reshape the route while strategy anchors it."},
      {id:"spms_metrics",module:8,source:"SPMS-M08-L03",name:"Actionable product metrics",summary:"Useful product metrics reduce uncertainty and guide a decision across business, product, customer, or marketing performance; impressive totals without a decision are vanity metrics.",confusions:["The largest available number is always the best metric.","Early products need only mature-company profit measures.","A metric remains useful even when no action could change from it."],caselet:"A startup celebrates total registrations while activation, repeat use, churn, acquisition cost, and cash risk remain unclear.",application:"Choose stage-relevant measures tied to decisions, such as activation, retention, contribution, and acquisition payback.",applicationWrong:["Increase the registration font size on the dashboard.","Track every possible number without owners or decisions.","Wait for mature profit history before measuring product behaviour."],bridge:"A metric earns its place when evidence can change resource allocation, product action, or risk response."},
      {id:"spms_privacy",module:8,source:"SPMS-M08-L05",name:"Privacy by design",summary:"Privacy by design makes lawful purpose, consent, minimisation, protection, user rights, and compliant partners part of the product from the start.",confusions:["Privacy is a notice added after data collection is complete.","A firm can ignore partner practices once data is outsourced.","All personal data may be reused whenever it improves a feature."],caselet:"An app collects broad personal data for an undefined future use and sends it to an unreviewed analytics vendor.",application:"Limit collection to a stated purpose, establish the lawful basis and user controls, protect the data, and verify the vendor's compliance before transfer.",applicationWrong:["Collect everything now and decide the purpose later.","Treat outsourcing as transfer of responsibility.","Rely only on a long terms-of-service page after collection."],bridge:"Data value does not remove accountability; product architecture determines whether privacy obligations can actually be honoured."}
    ],
    synthesis:[
      {id:"spms_syn_discovery",conceptId:"spms_jtbd",source:"SPMS-M01-L10",node:"Need to market",caselet:"A team has a technically feasible product for a huge TAM but cannot name the customer progress it improves.",stem:"What should happen before scaling?",correct:"Return to the customer job and desirability evidence, then narrow to a reachable segment whose unmet progress the product can serve.",wrong:["Increase TAM estimates until the business case works.","Add features because feasibility proves value.","Set a price before identifying the customer outcome."],explanation:"Market size and technical ability cannot replace a clear customer job and desirability evidence.",link:"Discovery connects the job, the desired value, and the first serviceable market before scale."},
      {id:"spms_syn_model",conceptId:"spms_unit_economics",source:"SPMS-M04-L07",node:"Value to economics",caselet:"Customers report high value and accept the price, but acquisition payback is longer than typical retention.",stem:"What does the evidence imply?",correct:"The offer may create value, but its acquisition or retention economics must change before growth is sustainable.",wrong:["High willingness to pay proves the whole model is viable.","Increase acquisition spending because each signup adds revenue.","Ignore retention when calculating lifetime value."],explanation:"Customer value and unit economics are separate necessary links in viability.",link:"Pricing captures value, but retention and contribution determine whether acquisition can be repaid."},
      {id:"spms_syn_plan",conceptId:"spms_roadmap",source:"SPMS-M07-L04",node:"Evidence to roadmap",caselet:"A new privacy requirement invalidates a planned data feature, but the roadmap still shows it as committed.",stem:"What is the responsible product response?",correct:"Trace the affected requirement, revise priorities and the roadmap, and communicate how the strategic outcome will be met safely.",wrong:["Build it unchanged because roadmaps cannot move.","Delete the privacy requirement from the backlog.","Hide the change until after release."],explanation:"Traceability and an adaptable roadmap let new evidence change delivery without losing strategic direction.",link:"A plan is credible when requirements, priorities, risks, and communication change together."},
      {id:"spms_syn_responsible",conceptId:"spms_privacy",source:"SPMS-M08-L05",node:"Metrics and responsibility",caselet:"A recommendation feature increases engagement but uses sensitive data outside the purpose users accepted.",stem:"Which decision best joins performance and responsibility?",correct:"Stop or redesign the data use, preserve purpose and consent, and measure whether a compliant alternative still delivers customer value.",wrong:["Keep it because engagement is the highest product metric.","Update the privacy notice after continuing the same processing.","Remove the engagement metric so the issue disappears."],explanation:"A performance improvement does not override privacy obligations or user trust.",link:"Responsible product management treats legal and human constraints as part of product value, not as external paperwork."}
    ]
  });

  window.T6_COURSES = catalogue;
})();
